import {labs} from './data.js';
import {$,intro} from './ui.js';
import {ohm,led,divider,rc,rl,regulator,amplifier} from './physics.mjs';
const range=(key,label,min,max,step,value,unit)=>({key,label,min,max,step,value,unit});
const check=(key,label,value=false)=>({key,label,value,type:'check'});
const choose=(key,label,options,value)=>({key,label,options,value,type:'select'});
const definitions={
led:{controls:[range('v','Supply voltage',1.5,9,.1,5,'V'),range('r','Series resistance',100,2200,10,330,'Ω'),choose('vf','LED example',[['2','Red · 2.0 V forward drop'],['3','Blue · 3.0 V forward drop']],2),check('reverse','Reverse the LED')],formula:'I = (Vsupply − Vf) / R',explain:'The resistor takes the voltage left after the LED’s forward drop. Its resistance sets the current through the whole series loop. More resistance means less current and usually less light. Current is not used up by the LED; energy is transferred to light and heat.',limit:'Constant forward-drop approximation; light is only a relative indicator. Example maximum current: 20 mA. Real LED forward voltage and ratings vary. A reversed LED is blocked here; a real one may be damaged by reverse voltage.',q:'Keep voltage fixed and double the resistance. What happens to LED current?',a:['It halves','It doubles','It stays the same'],correct:0,why:'The voltage across the resistor is unchanged, so I = V/R halves when R doubles.'},
ohm:{controls:[range('v','Supply voltage',1,12,.5,5,'V'),range('r','Resistance',100,5000,100,1000,'Ω')],formula:'I = V / R   ·   P = V × I',explain:'Voltage is a difference in electrical potential. In this closed loop it drives charge through the resistor. A greater resistance reduces the current for the same voltage. The resistor transfers electrical energy into heat.',limit:'Ideal DC source and resistor. The example resistor has a 0.25 W rating; real power ratings depend on temperature and mounting. Dot speed illustrates current, not the literal speed of electrons.',q:'Double voltage with resistance unchanged. What happens to resistor heating power?',a:['It doubles','It quadruples','It halves'],correct:1,why:'Current also doubles. P = V²/R, so multiplying voltage by two multiplies power by four.'},
divider:{controls:[range('r1','Top resistor R1',1,20,.5,10,'kΩ'),range('r2','Bottom resistor R2',1,20,.5,10,'kΩ'),check('load','Connect a 10 kΩ load across R2')],formula:'Vout = Vin × Rbottom / (R1 + Rbottom)',explain:'The two resistors share the 5 V supply. The midpoint voltage is measured relative to ground. When a load is connected, it is in parallel with R2. Their combined resistance falls, pulling the output lower.',limit:'Ideal 5 V supply. A divider is useful for signals and sensing, but it is not a regulated power supply. Here the connected load is a fixed 10 kΩ resistor; meters also have finite input resistance.',q:'What does adding a load across the lower resistor do to the output?',a:['Raises it','Lowers it','Nothing'],correct:1,why:'The load reduces the effective bottom resistance. A smaller share of the total voltage appears across it.'},
rc:{controls:[range('r','Resistance',1,20,1,10,'kΩ'),range('c','Capacitance',100,1000,100,100,'µF'),range('time','Elapsed time',0,5,.01,1,'τ'),check('discharge','Discharge from the supply voltage')],formula:'τ = R × C   ·   Vc = Vs × (1 − e^(−t/τ))',explain:'When charging begins, the capacitor voltage is low and current is largest. As voltage builds on the capacitor, less voltage remains across the resistor and the current falls. After one time constant, charging reaches about 63.2% of the final voltage.',limit:'Ideal 5 V source, resistor, and capacitor. Charging starts at 0 V; discharging starts at 5 V with the source disconnected. After 5τ it is close to the final value, never exactly there. Real capacitors have leakage, ESR, and tolerances.',q:'Double capacitance while keeping resistance the same. What happens to the time constant?',a:['It doubles','It halves','It is unchanged'],correct:0,why:'τ = R × C. Doubling capacitance doubles the time to reach the same fraction of the final voltage.'},
diode:{controls:[range('v','Supply voltage',0,5,.1,3,'V'),choose('vf','Diode example',[['0.7','Silicon · 0.7 V'],['0.3','Schottky · 0.3 V']],.7),check('reverse','Reverse the diode')],formula:'Forward: I ≈ max(0, Vs − Vf) / 1 kΩ',explain:'Anode toward the positive side makes this diode forward biased. Reverse it and the loop is blocked in this model. The cathode is the bar in the schematic and is often marked by a stripe on the package.',limit:'Constant forward-drop model with a 1 kΩ limiting resistor. Leakage, capacitance, recovery, and reverse breakdown are omitted. The symbol here uses an unfilled diode wedge; the cathode bar determines orientation.',q:'Which end of a typical axial diode does the painted stripe mark?',a:['Anode','Cathode','Either end'],correct:1,why:'The stripe usually marks the cathode, matching the bar of the diode symbol. Always confirm the specific part.'},
bjt:{controls:[range('drive','Base-drive voltage',0,5,.1,3.3,'V'),range('rb','Base resistor',1,100,1,10,'kΩ'),range('beta','Active-region gain β',50,200,10,100,'')],formula:'Ib ≈ (Vdrive − 0.7) / Rb; Ic ≈ min(βIb, load limit)',explain:'A small base current enables a larger collector current. At first, increasing base drive raises load current. Eventually the 220 Ω load and 5 V supply set the limit: the transistor is saturated and further drive adds little load current.',limit:'Simplified NPN model: Vbe = 0.7 V and Vce(sat) = 0.2 V. Gain varies with current, temperature, and device. Real switch designs use a conservative forced gain rather than assuming the typical β.',q:'Why does this base connection include a resistor?',a:['To limit base current','To store charge forever','To increase the supply voltage'],correct:0,why:'The base-emitter junction behaves like a diode. Without current limiting, it can draw excessive current from the driver.'},
mosfet:{controls:[check('drive','Set gate driver HIGH (5 V)',true),check('disconnected','Disconnect the gate driver'),check('pulldown','Keep 100 kΩ gate pull-down',true)],formula:'On: Iload = 5 V / (47 Ω + RDS(on))',explain:'The gate voltage relative to source controls the channel. A pull-down gives the gate a defined off state if the driver is disconnected. With neither driver nor pull-down, stored gate charge makes the state unpredictable.',limit:'An illustrative N-channel low-side switch, with RDS(on) = 0.10 Ω at 5 V. Transition behavior and body-diode conduction are not modeled. Choose a real part whose on-resistance is specified at your drive voltage; VGS(th) is not a full-on rating.',q:'An unplugged driver leaves the gate floating. Which part gives it a defined off state?',a:['A gate-to-source pull-down','A larger load resistor','A brighter LED'],correct:0,why:'A gate-to-source pull-down removes stored charge and returns VGS toward zero. It must be sized for the switching requirements.'},
regulator:{controls:[range('vin','Input voltage',3,12,.1,7,'V'),range('current','Load current',10,500,10,100,'mA')],formula:'Pheat ≈ (Vin − Vout) × Iout',explain:'This linear regulator aims for 3.3 V. It needs at least 0.4 V of input headroom in this model. When the input drops too low, the output falls out of regulation. Extra input voltage becomes heat rather than useful output power.',limit:'Illustrative LDO with fixed 0.4 V dropout, no ground current, and a constant-current load. Real dropout depends on current and temperature. Thermal shutdown, current limit, stability, and startup are not modeled.',q:'At the same output voltage and current, what does increasing input voltage do?',a:['Reduces heat','Increases heat','Eliminates dropout loss'],correct:1,why:'The regulator must lose more voltage at the same current. (Vin − Vout) × Iout increases.'},
opamp:{controls:[range('vin','Input signal',0,2,.05,.5,'V'),range('rf','Feedback resistor Rf',0,100,5,10,'kΩ')],formula:'Gain = 1 + Rf / Rg   ·   Vout = Gain × Vin',explain:'Negative feedback sets the non-inverting gain. The output is connected back to the minus input through Rf, with Rg = 10 kΩ to ground. If the requested output exceeds the supply, the amplifier clips and the gain formula no longer describes its actual output.',limit:'Ideal rail-to-rail op-amp on a 0–5 V supply, with unlimited bandwidth and no output loading. Real op-amps usually stop short of the rails and have input-range, current, offset, and bandwidth limits.',q:'A gain of 6 and a 1 V input asks for 6 V. What can this 5 V powered model do?',a:['Produce 6 V','Clip at its 5 V rail','Increase its supply'],correct:1,why:'Feedback cannot create supply headroom. The ideal model clips at 5 V; a real part may clip below that.'},
rl:{controls:[range('l','Inductance',10,500,10,100,'mH'),range('time','Elapsed time',0,5,.01,1,'τ')],formula:'τ = L / R   ·   I = (V / R) × (1 − e^(−t/τ))',explain:'Current cannot jump instantly through an ideal inductor. The magnetic field builds while current rises toward the limit set by the 100 Ω series resistor. A larger inductance slows that rise and stores more energy at the same current.',limit:'Ideal 5 V source, 100 Ω resistor, and initially unenergized inductor. Coil resistance, saturation, and switch-off are omitted. A real coil needs a suitable flyback or clamp path when its current is interrupted.',q:'What does an ideal inductor resist changing instantly?',a:['Its current','Its physical position','The resistor’s value'],correct:0,why:'V = L × dI/dt. A sudden current change would require a very large voltage. A flyback path lets stored energy dissipate safely.'},
pwm:{controls:[range('duty','Duty cycle',0,100,1,50,'%'),range('freq','Pulse frequency',100,2000,100,500,'Hz')],formula:'Duty cycle = ton / period   ·   Vaverage = 5 V × duty',explain:'The output switches between 0 V and 5 V. Duty cycle is the fraction of time spent high. The LED receives full on-state current during each pulse; changing duty cycle changes its average current. The plotted window is always 4 milliseconds.',limit:'Ideal 5 V digital output driving a red 2 V LED through 330 Ω. No switching losses or pin-voltage drop. Average voltage is not a smooth DC supply. Check real GPIO current limits; a transistor is needed for larger loads.',q:'At 25% duty cycle, the output is high for what fraction of each period?',a:['One quarter','Half','Three quarters'],correct:0,why:'Duty cycle is on-time divided by total period: 25% means on for one quarter and off for three quarters.'}
};
let states={},active='led',timer=null,animating=false;
export function cleanupLab(){clearInterval(timer);timer=null;animating=false}
export function lab(id){cleanupLab();active=labs.some(l=>l.id===id)?id:'led';const meta=labs.find(l=>l.id===active),d=definitions[active];if(!states[active])states[active]=Object.fromEntries(d.controls.map(c=>[c.key,c.value]));const s=states[active];
 $('#main').innerHTML=intro('02 / change something. learn something.','Your ideas.<br><em>In a circuit.</em>',meta.hint)+`<div class="lab-nav" aria-label="Choose an experiment">${labs.map(l=>`<button class="${active===l.id?'active':''}" data-lab="${l.id}" aria-pressed="${active===l.id}">${l.short}</button>`).join('')}</div><section class="lab-grid"><div class="simulation"><div class="sim-top"><span class="section-label">${meta.name}</span><span class="pill">LIVE MODEL</span></div><div id="circuit-svg"></div><p class="sim-note">Dotted motion represents conventional current (+ → −). It is an illustration, not a particle-speed measurement.</p></div><div class="lab-controls"><h3>What happens if…</h3>${d.controls.map(c=>c.type==='check'?`<label class="toggle-control"><input type="checkbox" data-control="${c.key}" ${s[c.key]?'checked':''}>${c.label}</label>`:c.type==='select'?`<div class="control"><label for="control-${c.key}">${c.label}</label><select id="control-${c.key}" data-control="${c.key}">${c.options.map(([v,n])=>`<option value="${v}" ${+v===+s[c.key]?'selected':''}>${n}</option>`).join('')}</select></div>`:`<div class="control"><label for="control-${c.key}">${c.label}<output id="out-${c.key}" for="control-${c.key}">${s[c.key]} ${c.unit}</output></label><input type="range" id="control-${c.key}" data-control="${c.key}" min="${c.min}" max="${c.max}" step="${c.step}" value="${s[c.key]}"><div class="range-ticks"><span>${c.min} ${c.unit}</span><span>${c.max} ${c.unit}</span></div></div>`).join('')}${['rc','rl'].includes(active)?'<button class="btn small" id="play-time">▶ Play over time</button>':''}<div id="lab-status" class="status-message" role="status"></div><p class="small-note">Try a change, then explain the result in your own words.</p></div></section><div class="metrics" id="metrics" aria-live="off"></div><div class="explanation-row"><section class="explanation"><h3>What you’re seeing</h3><div class="formula">${d.formula}</div><p>${d.explain}</p><p class="small-note"><strong>Model notes.</strong> ${d.limit}</p><a class="btn outline small" style="margin-top:16px" href="#explore/${meta.part}">Meet the component ↗</a></section><section class="challenge"><div class="eyebrow">Before you move on</div><h3>${d.q}</h3><div class="choices">${d.a.map((a,i)=>`<button data-answer="${i}">${a}</button>`).join('')}</div><p class="feedback" id="lab-feedback" role="status"></p></section></div>`;
 $('#main').onclick=e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.lab)location.hash='lab/'+b.dataset.lab;if(b.dataset.answer!==undefined){const correct=+b.dataset.answer===d.correct;document.querySelectorAll('[data-answer]').forEach(x=>x.classList.remove('correct','incorrect'));b.classList.add(correct?'correct':'incorrect');$('#lab-feedback').textContent=(correct?'Exactly. ':'Try again. ')+d.why}if(b.id==='play-time'){if(animating){cleanupLab();b.textContent='▶ Play over time'}else{animating=true;s.time=0;b.textContent='Ⅱ Pause';timer=setInterval(()=>{s.time=Math.min(5,s.time+.025);$('#control-time').value=s.time;update();if(s.time>=5){cleanupLab();b.textContent='↺ Play again'}},40)}}};
 $('#main').oninput=e=>{const c=e.target.dataset.control;if(!c)return;s[c]=e.target.type==='checkbox'?e.target.checked:+e.target.value;if(c==='time'&&animating){cleanupLab();$('#play-time').textContent='▶ Play over time'}update()};update();
 const chosen=document.querySelector(`[data-lab="${active}"]`);if(chosen)chosen.parentElement.scrollLeft=Math.max(0,chosen.offsetLeft-chosen.parentElement.offsetLeft-24);
}
const fixed=(v,n=2)=>Number(v).toFixed(n);
const metric=(name,val,unit)=>`<div class="metric"><label>${name}</label><strong>${val}</strong><small>${unit}</small></div>`;
const path=d=>`<path class="wire" d="${d}"/>`;
const txt=(x,y,text,cls='')=>`<text x="${x}" y="${y}" text-anchor="middle" class="${cls}">${text}</text>`;
const resistor=(x,y,label,vertical=false)=>`<g transform="translate(${x} ${y}) ${vertical?'rotate(90)':''}"><rect x="-42" y="-12" width="84" height="24" fill="#183e36"/><path class="symbol" d="M-42 0h12l5-10 10 20 10-20 10 20 10-20 10 20 5-10h12"/></g>${txt(x+(vertical?54:0),y+(vertical?4:-22),label)}`;
const battery=(v,x=110,y=170)=>path(`M${x} ${y-36}v26m0 20v26`)+`<path class="symbol" d="M${x-19} ${y-10}h38m-29 20h20"/>`+txt(x-50,y+4,v)+txt(x+29,y-11,'+');
const diode=(x,y,reverse=false,isLed=false,light=0)=>`<g transform="translate(${x} ${y}) ${reverse?'rotate(180)':''}"><rect x="-35" y="-38" width="70" height="78" fill="#183e36"/>${isLed?`<circle r="38" fill="#ed975c" opacity="${light*.45}"/><circle r="29" fill="#ed975c" opacity="${light*.4}"/>`:''}<path d="M0-38v23M-15-15h30L0 12ZM-17 12h34M0 12v28" class="symbol"/>${isLed?'<path d="M24-9l13-11m-5 0h5v5M30 7 43-4m-5 0h5v5" class="wire"/>':''}</g>`;
function loop(v,r,device,flowOn=true){return path('M110 134V75H450V270H110V206')+`<path class="flow ${flowOn?'':'still'}" d="M110 134V75H450V270H110V206"/>`+battery(v)+resistor(280,75,r)+device+txt(280,307,'Closed series loop');}
function graph(curve,point,label,top=5){const gx=80,gy=65,w=410,h=180;let pts=Array.from({length:101},(_,i)=>`${gx+i*w/100},${gy+h-curve(i/100)*h/top}`).join(' ');return path(`M${gx} ${gy}v${h}h${w}`)+[.25,.5,.75,1].map(v=>`<path d="M${gx} ${gy+h-v*h}h${w}" stroke="#608063" opacity=".25"/>`).join('')+`<polyline points="${pts}" fill="none" stroke="#d6ed99" stroke-width="3"/><path d="M${gx+point*w} ${gy}v${h}" stroke="#ed975c" stroke-dasharray="4 5"/><circle cx="${gx+point*w}" cy="${gy+h-curve(point)*h/top}" r="6" fill="#ed975c"/>`+txt(gx-25,gy+6,top)+txt(gx-20,gy+h,0)+txt(gx,gy+h+24,'0')+txt(gx+w/5,gy+h+24,'1τ')+txt(gx+w,gy+h+24,'5τ')+txt(290,30,label)+txt(285,302,'Time →');}
function update(){const s=states[active];let svg='',metrics=[],status='',warn=false;definitions[active].controls.filter(c=>!c.type).forEach(c=>$('#out-'+c.key).textContent=`${+s[c.key].toFixed(2)} ${c.unit}`);
if(active==='led'||active==='diode'){const r=active==='led'?s.r:1000,a=led(s.v,r,s.vf,s.reverse);metrics=[['Loop current',fixed(a.i*1000),'mA'],['Resistor heat',fixed(a.p*1000,1),'mW'],[active==='led'?'Relative light':'Diode orientation',active==='led'?Math.round(a.brightness*100):(s.reverse?'Reverse':'Forward'),active==='led'?'% of 20 mA reference':'bias']];status=s.reverse?'Reverse biased: current is blocked in this model.':a.i===0?'Below the modeled forward voltage: no current.':a.i>.02?'Above the example 20 mA limit. Increase resistance.':'Current flows through the resistor and diode.';warn=a.i>.02||s.reverse&&s.v>3;svg=loop(s.v+' V',r+' Ω',diode(450,170,s.reverse,active==='led',a.brightness),a.i>0)+txt(495,222,'Vf '+s.vf+' V');}
if(active==='ohm'){const a=ohm(s.v,s.r);metrics=[['Current',fixed(a.i*1000),'mA'],['Power / heating',fixed(a.p*1000,1),'mW'],['Resistor rating',250,'mW example']];warn=a.p>.25;status=warn?'Exceeds the example ¼ W resistor rating.':'Within the example ¼ W resistor rating.';svg=loop(s.v+' V',s.r+' Ω','',true)+txt(280,165,fixed(a.i*1000)+' mA','big-value')+txt(280,197,'I = V / R');}
if(active==='divider'){const a=divider(5,s.r1*1000,s.r2*1000,s.load?10000:Infinity);metrics=[['Output voltage',fixed(a.out),'V'],['Supply current',fixed(a.i*1000,3),'mA'],['Effective lower R',fixed(a.bottom/1000),'kΩ']];status=s.load?'The 10 kΩ load is in parallel with R2.':'No load connected: the basic divider formula applies.';svg=path('M110 134V45H345V280H110V206M345 165h140')+battery('5 V')+resistor(345,102,s.r1+'k',true)+resistor(345,225,s.r2+'k',true)+`<circle cx="345" cy="165" r="5" fill="#d6ed99"/>`+txt(475,145,fixed(a.out)+' V','big-value')+txt(475,189,'Vout')+txt(180,303,'Ground / 0 V');if(s.load)svg+=path('M460 165v115H345')+resistor(460,230,'10k load',true);}
if(active==='rc'){const tau=s.r*1000*s.c*1e-6,a=rc(5,s.r*1000,s.c*1e-6,s.time*tau,s.discharge);$('#out-time').textContent=`${fixed(s.time*tau)} s · ${fixed(s.time,1)}τ`;metrics=[['Capacitor voltage',fixed(a.vc),'V'],['Current magnitude',fixed(Math.abs(a.i)*1000,3),'mA'],['Time constant τ',fixed(tau),'s']];status=s.discharge?'Discharging through R: energy leaves the capacitor.':'Charging through R: current slows as voltage rises.';svg=graph(x=>rc(5,s.r*1000,s.c*1e-6,x*5*tau,s.discharge).vc,s.time/5,'Capacitor voltage (V)');svg+=`<g transform="translate(455 18) scale(.46)">${path('M-90 0h30m120 0h60v80H-90V0')}${resistor(0,0,'R')}<path class="symbol" d="M120 20v12m-20 0h40m-40 16h40m-20 0v30"/>${txt(174,47,'C')}</g>`;}
if(active==='bjt'){const ib=Math.max(0,(s.drive-.7)/(s.rb*1000)),ic=Math.min(s.beta*ib,4.8/220),sat=s.beta*ib>=4.8/220;metrics=[['Base current',fixed(ib*1000,3),'mA'],['Collector current',fixed(ic*1000,2),'mA'],['Collector–emitter',fixed(5-ic*220),'V']];status=ib===0?'No forward base drive: transistor off.':sat?'Saturated: the load limits the current.':'Active region: collector current follows base drive.';svg=transistorCircuit(false,ic>0,s.drive+' V',s.rb+'k',false)+txt(452,101,'220 Ω');}
if(active==='mosfet'){const unknown=s.disconnected&&!s.pulldown,on=!s.disconnected&&s.drive,current=on?5/47.1:0;metrics=[['Gate-to-source',unknown?'?':on?'5.0':'0.0','V'],['Load current',unknown?'?':fixed(current*1000),'mA'],['MOSFET heat',unknown?'?':fixed(current*current*.1*1000,2),'mW']];status=unknown?'Floating gate: state unknown. Restore a pull-down or driver.':on?'5 V gate drive: the modeled channel is on.':'Gate at 0 V: the modeled switch is off.';warn=unknown;svg=transistorCircuit(true,on,unknown?'Floating':on?'5 V':'0 V','Gate',s.disconnected,s.pulldown)+txt(450,100,'47 Ω');}
if(active==='regulator'){const a=regulator(s.vin,3.3,s.current/1000);metrics=[['Output voltage',fixed(a.out),'V'],['Heat dissipated',fixed(a.p,2),'W'],['Ideal efficiency',fixed(a.eff*100,0),'%']];warn=!a.inRegulation||a.p>.5;status=!a.inRegulation?'In dropout: insufficient input headroom for 3.3 V.':a.p>.5?'Regulating, but heat is significant. Thermal design matters.':'Regulating at 3.3 V with enough input headroom.';svg=path('M100 140h90m180 0h90M280 204v65H100V175M460 140v129H280')+`<rect class="symbol" x="190" y="95" width="180" height="110" rx="8"/>`+txt(280,131,'LINEAR REGULATOR')+txt(280,161,'Target 3.3 V')+txt(100,118,s.vin+' V')+txt(464,118,fixed(a.out)+' V','big-value')+txt(280,294,'Ground')+resistor(460,206,'Load',true)+txt(280,235,fixed(a.p)+' W as heat');}
if(active==='opamp'){const a=amplifier(s.vin,s.rf,10);metrics=[['Requested gain',fixed(a.gain,1),'×'],['Ideal request',fixed(a.ideal),'V'],['Actual output',fixed(a.out),'V']];warn=a.clipped;status=a.clipped?'Output clips at the 5 V rail in this ideal model.':'Negative feedback keeps the output at the requested gain.';svg=path('M75 113h140M345 155h140M420 155v108H170V193h45M170 263H65v32M280 109V55M280 201v34')+`<path d="M215 80v150l130-75Z" class="symbol"/>`+txt(232,119,'+')+txt(232,199,'−')+txt(280,46,'+5 V')+txt(280,250,'0 V')+txt(100,96,s.vin+' V')+txt(475,135,fixed(a.out)+' V','big-value')+resistor(300,263,s.rf+'k Rf')+resistor(100,263,'10k Rg')+txt(65,319,'GND');}
if(active==='rl'){const tau=s.l/1000/100,a=rl(5,100,s.l/1000,s.time*tau);$('#out-time').textContent=`${fixed(s.time*tau*1000)} ms · ${fixed(s.time,1)}τ`;metrics=[['Inductor current',fixed(a.i*1000),'mA'],['Stored energy',fixed(a.energy*1e6,1),'µJ'],['Time constant τ',fixed(tau*1000,2),'ms']];status='Current approaches 50 mA, set by 5 V / 100 Ω.';svg=graph(x=>rl(5,100,s.l/1000,x*5*tau).i*1000,s.time/5,'Inductor current (mA)',50);}
if(active==='pwm'){const duty=s.duty/100;metrics=[['Average LED current',fixed(3/330*1000*duty),'mA'],['Average output',fixed(5*duty),'V'],['Pulse period',fixed(1000/s.freq),'ms']];status=s.duty===0?'Always low: LED is off.':s.duty===100?'Always high: LED is continuously on.':`High for ${s.duty}% of each period; peak LED current stays 9.09 mA.`;const x0=70,y0=245,w=430,h=150,cycles=s.freq*.004;let d=`M${x0} ${s.duty===0?y0:y0-h}`;if(s.duty===100)d+=`H${x0+w}`;else if(s.duty===0)d+=`H${x0+w}`;else{for(let i=0;i<Math.ceil(cycles);i++){const end=Math.min(w,w*(i+duty)/cycles),start=Math.min(w,w*(i+1)/cycles);d+=`H${x0+end}V${y0}H${x0+start}`;if(start<w)d+=`V${y0-h}`}}svg=path('M70 75v170h430')+`<path d="${d}" fill="none" stroke="#d6ed99" stroke-width="3"/>`+txt(40,100,'5 V')+txt(40,248,'0 V')+txt(70,275,'0')+txt(500,275,'4 ms')+txt(280,36,'Digital output voltage')+txt(285,310,'Time →');}
$('#circuit-svg').innerHTML=`<svg viewBox="0 0 570 335" role="img" aria-label="${labs.find(x=>x.id===active).name} interactive circuit illustration">${svg}</svg>`;$('#metrics').innerHTML=metrics.map(m=>metric(...m)).join('');$('#lab-status').textContent=status;$('#lab-status').classList.toggle('warning',warn);
}
function transistorCircuit(mos,on,drive,label,disconnected,pulldown){
 let svg=path('M295 45h70v98M365 220v70H110M110 180h205')+resistor(365,92,'',true)+txt(295,35,'+5 V')+txt(128,160,drive)+txt(150,318,'0 V / common ground');
 if(disconnected)svg+='<rect x="184" y="168" width="30" height="24" fill="#183e36"/>'+path('M183 180l30-18');
 if(mos){svg+='<path class="symbol" d="M315 150v60m9-60v60m10-60v60M334 156h31v-13M334 204h31v16"/>'+txt(307,141,'G')+txt(391,153,'D')+txt(391,225,'S');if(pulldown)svg+=path('M250 180v110')+resistor(250,238,'100k',true);if(on)svg+='<path class="flow" d="M295 45h70v111h-31v48h31v86H110"/>';}
 else{svg+='<path class="symbol" d="M315 152v56M315 164l50-29v8M315 195l50 27v-2M350 207l15 15-19-3"/>'+resistor(219,180,label)+txt(301,141,'B')+txt(391,150,'C')+txt(391,232,'E');if(on)svg+='<path class="flow" d="M295 45h70v90l-50 29v31l50 27v68H110"/>';}
 return svg;
}
